import requests
import pandas as pd


def task_func(url: str) -> pd.DataFrame:
    try:
        response = requests.get(url, timeout=5)
        response.raise_for_status()
        try:
            data = response.json()
            return pd.DataFrame(data)
        except ValueError as exc:
            raise ValueError("Fetched data is not valid JSON or cannot be converted into a DataFrame.") from exc
    except requests.RequestException as exc:
        raise SystemError(f"Network-related error while fetching data from {url}: {exc}") from exc
